from flask import Flask, render_template,redirect,request,url_for,flash,session
from models import db,Product
import sqlite3
from werkzeug.utils import secure_filename
import os
app = Flask(__name__)

@app.route('/')
def home():
    return render_template('index.html')

@app.route('/login')
def login():
    return render_template('login.html')

@app.route('/register')
def register():
    return render_template('register.html')

@app.route('/dashboard')
def dashboard():
    conn = sqlite3.connect("products.db")
    c = conn.cursor()

    c.execute("SELECT * FROM products")
    products = c.fetchall()

    conn.close()

    return render_template(
        'dashboard.html',
        products=products
    )
def products():

    keyword = request.args.get('keyword', '')

    products = Product.query.filter(
        Product.name.contains(keyword)
    ).all()

    return render_template(
        'products.html',
        products=products

    )
@app.route("/edit_product/<int:id>", methods=["GET", "POST"])
def edit_product(id):
    conn = sqlite3.connect("products.db")
    c = conn.cursor()

    if request.method == "POST":
        name = request.form["name"]
        category = request.form["category"]
        price = request.form["price"]
        quantity = request.form["quantity"]
        code = request.form["code"]

        image = request.files["image"]

        if image and image.filename != "":
            filename = secure_filename(image.filename)
            image.save(os.path.join("static/uploads", filename))

            c.execute("""
                UPDATE products
                SET name=?, category=?, price=?, quantity=?, code=?, image=?
                WHERE id=?
            """, (name, category, price, quantity, code, filename, id))
        else:
            c.execute("""
                UPDATE products
                SET name=?, category=?, price=?, quantity=?, code=?
                WHERE id=?
            """, (name, category, price, quantity, code, id))

        conn.commit()
        conn.close()

        return redirect("/dashboard")

    c.execute("SELECT * FROM products WHERE id=?", (id,))
    product = c.fetchone()

    conn.close()

    return render_template("edit_product.html", product=product)

from flask import Flask, render_template,redirect,request,url_for,flash,session
from models import db,Product
import sqlite3
from werkzeug.utils import secure_filename
import os
app = Flask(__name__)

@app.route('/')
def home():
    return render_template('index.html')

@app.route('/login')
def login():
    return render_template('login.html')

@app.route('/register')
def register():
    return render_template('register.html')

@app.route('/dashboard')
def dashboard():
    conn = sqlite3.connect("products.db")
    c = conn.cursor()

    c.execute("SELECT * FROM products")
    products = c.fetchall()

    conn.close()

    return render_template(
        'dashboard.html',
        products=products
    )
def products():

    keyword = request.args.get('keyword', '')

    products = Product.query.filter(
        Product.name.contains(keyword)
    ).all()

    return render_template(
        'products.html',
        products=products

    )
@app.route("/edit_product/<int:id>", methods=["GET", "POST"])
def edit_product(id):
    conn = sqlite3.connect("products.db")
    c = conn.cursor()

    if request.method == "POST":
        name = request.form["name"]
        category = request.form["category"]
        price = request.form["price"]
        quantity = request.form["quantity"]
        code = request.form["code"]

        image = request.files["image"]

        if image and image.filename != "":
            filename = secure_filename(image.filename)
            image.save(os.path.join("static/uploads", filename))

            c.execute("""
                UPDATE products
                SET name=?, category=?, price=?, quantity=?, code=?, image=?
                WHERE id=?
            """, (name, category, price, quantity, code, filename, id))
        else:
            c.execute("""
                UPDATE products
                SET name=?, category=?, price=?, quantity=?, code=?
                WHERE id=?
            """, (name, category, price, quantity, code, id))

        conn.commit()
        conn.close()

        return redirect("/dashboard")

    c.execute("SELECT * FROM products WHERE id=?", (id,))
    product = c.fetchone()

    conn.close()

    return render_template("edit_product.html", product=product)

*{
    margin:0;
    padding:0;
    box-sizing:border-box;
    font-family:Arial, sans-serif;
}
.container{
    min-height:100vh;
    display:flex;
    justify-content:flex-end;
    align-items:center;
    padding-right: 100px;
}

.card{
    width:500px;
    background:white;
    padding:40px;
    border-radius:20px;
    box-shadow:0 5px 20px rgba(193, 79, 79, 0.1);
}

.icon{
    width:80px;
    height:80px;
    margin:auto;
    border-radius:50%;
    background:#eef3ff;
    display:flex;
    justify-content:center;
    align-items:center;
    font-size:35px;
}

h1{
    text-align:center;
    margin-top:20px;
}

p{
    text-align:center;
    color:#666;
    margin-bottom:25px;
}

label{
    display:block;
    margin-top:15px;
    margin-bottom:5px;
}

input{
    width:100%;
    padding:12px;
    border:1px solid #ddd;
    border-radius:10px;
}

button{
    width:100%;
    padding:14px;
    margin-top:25px;
    border:none;
    border-radius:10px;
    background:#2563eb;
    color:rgb(80, 19, 19);
    font-size:16px;
    cursor:pointer;
}

button:hover{
    background:#1d4ed8;
}

.link{
    text-align:center;
    margin-top:20px;
}
body{
    margin:0;
    font-family:Arial, sans-serif;
}


.sidebar{
    width:250px;
    height:100vh;

    position:fixed;
    left:0;
    top:0;

    background: linear-gradient(135deg,#848db7,#764ba2);
    color:white;
}

.sidebar h2{
    text-align:center;
    padding:20px 0;

}

.sidebar ul{
    list-style:none;
    padding:0;
}

.sidebar li{
    padding:15px 20px;
}

.sidebar a{
    color:white;
    text-decoration:none;
}

.sidebar li:hover{
    background:#9099b1;
}


.main-content{
    margin-left:250px;
    padding:30px;
    background: linear-gradient(135deg,#c5c8d3,#2e0f4c);
    min-height:100vh;

}

.topbar{
    display:flex;
    justify-content:space-between;
    align-items:center;
}

.cards{
    display:flex;
    gap:20px;
    margin-top:20px;
}

.card-box{
    flex:1;
    background:white;
    padding:25px;

    border-radius:15px;

    box-shadow:0 3px 10px rgba(0,0,0,.1);
}

.card-box h2{
    color:#fcfcfc;
}


.search-box{
    margin-top:30px;
}

.search-box input{
    width:300px;
    padding:10px;
}

.search-box button{
    padding:10px 15px;
}


.table-container{
    margin-top:30px;

    background:rgb(255, 255, 255);

    padding:20px;

    border-radius:15px;

    box-shadow:0 3px 10px rgba(0,0,0,.1);
}

table{
    width:100%;
    border-collapse:collapse;
}

table th,
table td{
    border-bottom:1px solid #967373;
    padding:12px;
    text-align:center;
}

.btn-edit{
    background:#10b981;
    color:white;
    padding:8px 12px;
    border-radius:5px;
    text-decoration:none;
}

.btn-delete{
    background:#ef4444;
    color:white;
    padding:8px 12px;
    border-radius:5px;
    text-decoration:none;
}
.welcome-box p{
    color: #ffffff;
    font-size: 18px;
    font-weight: 500;
}

.auth-page {
    background-image: url("background.jpg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    min-height: 100vh;
}
.search-box{
    margin-top:30px;
    margin-bottom:20px;
}

.search-box button{
    width:auto;
    padding:10px 20px;
    margin-left:10px;
}
.dashboard-header{
    display:flex;
    justify-content:space-between;
    align-items:center;
    margin-bottom:25px;
}

.dashboard-header h1{
    margin-bottom:5px;
}

.dashboard-header p{
    color:#ffffff;
}

.add-btn{
    width:auto;
    padding:10px 18px;
    background:#2563eb;
    color:white;
}

.top-search{
    margin-bottom:20px;
}

.top-search input{
    width:350px;
    padding:12px;
    border:1px solid #ddd;
    border-radius:10px;
}

.cards{
    display:grid;
    grid-template-columns:repeat(4,1fr);
    gap:20px;
    margin-bottom:25px;
}

.card-box{
    background:rgb(255, 255, 255);
    padding:25px;
    border-radius:15px;
    box-shadow:0 3px 10px rgba(0,0,0,.1);
}

.card-box h2{
    color:#516da9;
    font-size:32px;
    margin-bottom:10px;
}

.welcome-box{
    background:white;
    padding:25px;
    border-radius:15px;
    margin-bottom:25px;
    box-shadow:0 3px 10px rgba(0,0,0,.1);
}

.welcome-box h2{
    margin-bottom:10px;
}

.welcome-box p{
    color:#666;
}

.product-info img{
    width:60px;
    height:60px;
    object-fit:cover;
    border-radius:8px;
    border:1px solid #ddd;
}
.delete-btn{
    background: #e74c3c;
    color: white;
    padding: 6px 10px;
    border-radius: 5px;
    text-decoration: none;
}

.delete-btn:hover{
    opacity: 0.8;
}
.user-info{
    text-align: center;
    color: white;
}

.logout{
    display: block;
    text-align: center;
    color: white;
    text-decoration: none;
}

